<?php declare( strict_types=1 ); namespace Inc\Repositories\WPDBRepositories; use Inc\DTO\Exam\ExamOutboxEventDTO; use Inc\Enums\Settings\TableName; class ExamOutboxEventRepository { private \wpdb $wpdb; private string $table; public function __construct( ?\wpdb $wpdb = null ) { $this->wpdb = $wpdb ?? $GLOBALS['wpdb']; $this->table = TableName::ExamOutbox->prefixed(); } public function insert( array $data ): int { $this->wpdb->insert( $this->table, $data ); return (int) $this->wpdb->insert_id; } public function find( int $id ): ?ExamOutboxEventDTO { $row = $this->wpdb->get_row( $this->wpdb->prepare( "SELECT * FROM %i WHERE id = %d", $this->table, $id ), ARRAY_A ); return $row ? ExamOutboxEventDTO::fromArray( $row ) : null; } public function findPending(): array { $rows = $this->wpdb->get_results( $this->wpdb->prepare( "SELECT * FROM %i WHERE processed_at IS NULL AND available_at <= NOW() ORDER BY available_at ASC LIMIT 100", $this->table ), ARRAY_A ); return array_map( [ ExamOutboxEventDTO::class, 'fromArray' ], $rows ?: [] ); } public function update( int $id, array $data ): bool { return false !== $this->wpdb->update( $this->table, $data, [ 'id' => $id ] ); } }
